sealed trait Expr { def children: List[Expr] }

case class Lit(value: Int) extends Expr { def children = Nil }
case class Add(left: Expr, right: Expr) extends Expr {
  def children = List(left, right)
}

def walk(e: Expr)(f: Expr => Unit): Unit = {
  f(e)
  e.children.foreach(walk(_)(f))
}

def eval(e: Expr): Int = e match {
  case Lit(v)    => v
  case Add(l, r) => eval(l) + eval(r)
}
